#!/usr/bin/env bash
#
# Backfill Bluesky pivot `provider_post_id` (record CID -> AT-URI).
#
# Posts published before the analytics fix stored the record CID in
# `mixpost_post_accounts.provider_post_id`, while insights are keyed by the
# AT-URI (kept in the pivot `data` payload). That mismatch left those posts
# without analytics. This realigns `provider_post_id` to the AT-URI and moves
# the old CID into the pivot `data` payload under the `cid` key.
#
# Run once from your Mixpost Pro or Enterprise project root:
#   ./backfill-bluesky-provider-post-id.sh
# Or pass the project root explicitly:
#   ./backfill-bluesky-provider-post-id.sh /var/www/my-app
#
# Safe to run more than once: rows that are already correct are skipped.

set -euo pipefail

APP_DIR="${1:-$(pwd)}"

if [ ! -f "$APP_DIR/artisan" ]; then
    echo "Error: '$APP_DIR' does not look like the project root." >&2
    echo "Run this from your project root, or pass the project root as the first argument." >&2
    exit 1
fi

php "$APP_DIR/artisan" tinker --execute='
(function () {
    $blueskyAccountIds = \Illuminate\Support\Facades\DB::table("mixpost_accounts")
        ->where("provider", "bluesky")
        ->pluck("id");

    if ($blueskyAccountIds->isEmpty()) {
        echo "No Bluesky accounts found. Nothing to backfill." . PHP_EOL;
        return;
    }

    $updated = 0;

    \Illuminate\Support\Facades\DB::table("mixpost_post_accounts")
        ->whereIn("account_id", $blueskyAccountIds)
        ->whereNotNull("data")
        ->orderBy("id")
        ->chunkById(200, function ($rows) use (&$updated) {
            foreach ($rows as $row) {
                $data = json_decode($row->data, true) ?? [];
                $uri = \Illuminate\Support\Arr::get($data, "uri");

                if (! $uri || $row->provider_post_id === $uri) {
                    continue;
                }

                $data["cid"] = $row->provider_post_id;

                \Illuminate\Support\Facades\DB::table("mixpost_post_accounts")
                    ->where("id", $row->id)
                    ->update([
                        "provider_post_id" => $uri,
                        "data" => json_encode($data),
                    ]);

                $updated++;
            }
        });

    echo "Backfilled {$updated} Bluesky post(s)." . PHP_EOL;
})();
'
